import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as t,o as i,af as o}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const u=JSON.parse('{"title":"Grok Imagine","description":"","frontmatter":{},"headers":[],"relativePath":"products/ai-coding/grok/grok-imagine.md","filePath":"products/ai-coding/grok/grok-imagine.md","lastUpdated":1787110548000}'),s={name:"products/ai-coding/grok/grok-imagine.md"};function r(n,e,d,l,g,p){return i(),t("div",null,[...e[0]||(e[0]=[o(`<h1 id="grok-imagine" tabindex="-1">Grok Imagine <a class="header-anchor" href="#grok-imagine" aria-label="Permalink to &quot;Grok Imagine&quot;">​</a></h1><blockquote><p><strong>Imagine</strong> is xAI&#39;s image and video surface. Official consumer entry is <a href="https://grok.com/imagine" target="_blank" rel="noreferrer">grok.com/imagine</a>. Official API entry is the <a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">Imagine API</a>: &quot;The Imagine API lets you generate and edit images and videos with Grok Imagine models.&quot;</p><p>This page maps the <strong>product</strong> (chat + grok.com/imagine + iOS/Android) and the <strong>API</strong>. Analog: Claude Design / Gemini Flow — a creative surface, <strong>not</strong> a coding agent.</p></blockquote><h2 id="goals-and-non-goals" tabindex="-1">Goals and non-goals <a class="header-anchor" href="#goals-and-non-goals" aria-label="Permalink to &quot;Goals and non-goals&quot;">​</a></h2><p><strong>Audience:</strong> people who want images or short video from Grok, either in the app or from <code>api.x.ai</code>.</p><p><strong>Goals:</strong> separate product Imagine from the Imagine API, list official models and workflows, point at docs.</p><p><strong>Non-goals:</strong> a second copy of the full REST reference, invented quotas, or third-party &quot;Grok 4.3 / 2M token&quot; claims. Do not treat Imagine as Grok Build.</p><h2 id="two-doors" tabindex="-1">Two doors <a class="header-anchor" href="#two-doors" aria-label="Permalink to &quot;Two doors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Door</th><th>Who it is for</th><th>Entry</th></tr></thead><tbody><tr><td><strong>Product Imagine</strong></td><td>Chat users on grok.com / iOS / Android</td><td><a href="https://grok.com/imagine" target="_blank" rel="noreferrer">grok.com/imagine</a>, or generate inside a <a href="./grok-chat.html">Grok Chat</a> thread</td></tr><tr><td><strong>Imagine API</strong></td><td>Your own app</td><td><a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">docs.x.ai/developers/model-capabilities/imagine</a>, playground on <a href="https://console.x.ai" target="_blank" rel="noreferrer">console.x.ai</a></td></tr></tbody></table><p><a href="https://x.ai/grok" target="_blank" rel="noreferrer">x.ai/grok</a> describes the product in one line: generate images and video from text or reference photos; restyle, edit, and iterate without leaving the conversation. Marketing numbers on that page: <strong>up to 2K</strong> stills and <strong>15-second</strong> videos (video also listed as &quot;up to 15 seconds at 720p&quot; in the feature grid — resolution caps also depend on plan, see FAQ).</p><p>Paid usage draws from the <strong>same weekly SuperGrok pool</strong> as Chat / Voice / Build (<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>). This page does not invent how many images a plan includes.</p><h2 id="product-imagine" tabindex="-1">Product Imagine <a class="header-anchor" href="#product-imagine" aria-label="Permalink to &quot;Product Imagine&quot;">​</a></h2><p>Official consumer facts:</p><ul><li><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">overview</a>: &quot;Create images and video with Grok Imagine.&quot;</li><li><a href="https://x.ai/news/grok-imagine-image-2" target="_blank" rel="noreferrer">x.ai/news/grok-imagine-image-2</a> (2026-08-07): <strong>Imagine Image 2.0</strong> is generally available as <strong>Quality Mode</strong> on grok.com/imagine and the iOS / Android apps.</li><li>Same post: product tools include a <strong>magic wand</strong> (edit the region you point at), <strong>segmentation</strong>, <strong>background removal</strong>, <strong>multi-ref editing (up to 5 input images)</strong>, <strong>smart resize</strong> to another aspect ratio, and <strong>templates</strong> (photo edit, product shots, headshots, icons, game assets, and more).</li><li><a href="https://x.ai/news/grok-imagine-video-1-5-references" target="_blank" rel="noreferrer">x.ai/news/grok-imagine-video-1-5-references</a> (2026-07-31): <strong>text-to-video</strong> and <strong>native 1080p</strong> (text-to-video and image-to-video) are generally available on grok.com/imagine, iOS, and Android. Image + voice references started in the US for SuperGrok Heavy and SuperGrok Plus, then rolled out. Up to <strong>seven</strong> image references per generation.</li></ul><h3 id="product-rules-you-will-hit-faq" tabindex="-1">Product rules you will hit (<a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">FAQ</a>) <a class="header-anchor" href="#product-rules-you-will-hit-faq" aria-label="Permalink to &quot;Product rules you will hit ([FAQ](https://docs.x.ai/grok/faq))&quot;">​</a></h3><ul><li>Generated images and videos include a <strong>Grok watermark</strong>. There is no setting to remove it. Removing, altering, or obscuring the watermark is prohibited under the Acceptable Use Policy.</li><li>Enabling <strong>NSFW</strong> does <strong>not</strong> turn off moderation. CSAM and non-consensual intimate imagery are never permitted.</li><li><strong>720p videos automatically fall back to 480p</strong> once you hit the 720p cap for your tier.</li></ul><h2 id="imagine-api" tabindex="-1">Imagine API <a class="header-anchor" href="#imagine-api" aria-label="Permalink to &quot;Imagine API&quot;">​</a></h2><p>Official overview (<a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">imagine</a>): image generation, image editing with up to <strong>3</strong> reference images, video from text or stills, video editing, reference-to-video, video extension, and Files API integration.</p><p>That <strong>3-image API edit cap</strong> is not the same number as the product&#39;s &quot;up to 5 input images&quot; on Image 2.0. Quote the page you are on.</p><h3 id="models-official-slugs" tabindex="-1">Models (official slugs) <a class="header-anchor" href="#models-official-slugs" aria-label="Permalink to &quot;Models (official slugs)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Job</th><th>Official pick (<a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">developers/models</a>, <a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">imagine</a>)</th></tr></thead><tbody><tr><td>Images</td><td><code>grok-imagine-image-2.0</code></td></tr><tr><td>Videos</td><td><code>grok-imagine-video-1.5</code></td></tr></tbody></table><p><a href="https://x.ai/api/imagine" target="_blank" rel="noreferrer">x.ai/api/imagine</a>: up to <strong>2K</strong> resolution, <strong>10 images per request</strong>, video <strong>up to 15s</strong>. Image generation is <strong>flat per-image</strong>. Image edits bill <strong>input + output</strong>. Video is <strong>per-second</strong>, duration and resolution both affect cost. Prices live on <a href="https://docs.x.ai/developers/models" target="_blank" rel="noreferrer">developers/models</a> / <a href="https://docs.x.ai/developers/pricing#imagine-api-pricing" target="_blank" rel="noreferrer">pricing</a> — do not copy a third-party table.</p><h3 id="image-generation" tabindex="-1">Image generation <a class="header-anchor" href="#image-generation" aria-label="Permalink to &quot;Image generation&quot;">​</a></h3><p>Endpoint: <code>POST https://api.x.ai/v1/images/generations</code>. Official knobs (<a href="https://docs.x.ai/developers/model-capabilities/images/generation" target="_blank" rel="noreferrer">images/generation</a>):</p><ul><li><code>n</code> — multiple images in one request (overview: up to 10).</li><li><code>aspect_ratio</code> — <code>1:1</code>, <code>16:9</code> / <code>9:16</code>, <code>4:3</code> / <code>3:4</code>, <code>3:2</code> / <code>2:3</code>, <code>2:1</code> / <code>1:2</code>, <code>19.5:9</code> / <code>9:19.5</code>, <code>20:9</code> / <code>9:20</code>, <code>auto</code>.</li><li><code>resolution</code> — <code>1k</code> or <code>2k</code>.</li><li><code>quality</code> — <code>low</code> or <code>medium</code> (default <code>medium</code>). <strong>Only</strong> on <code>grok-imagine-image-2.0</code>.</li><li>Default return is a <strong>temporary URL</strong>. Download promptly, or request base64.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.x.ai/v1/images/generations</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$XAI_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;model&quot;: &quot;grok-imagine-image-2.0&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;prompt&quot;: &quot;A collage of London landmarks in a stenciled street-art style&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;aspect_ratio&quot;: &quot;16:9&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;resolution&quot;: &quot;2k&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span></span></code></pre></div><p>Edit path: <code>POST https://api.x.ai/v1/images/edits</code> with a public URL or <code>data:</code> URI (<a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">imagine</a>).</p><h3 id="video-generation" tabindex="-1">Video generation <a class="header-anchor" href="#video-generation" aria-label="Permalink to &quot;Video generation&quot;">​</a></h3><p>Endpoint: <code>POST https://api.x.ai/v1/videos/generations</code>, then poll <code>GET https://api.x.ai/v1/videos/{request_id}</code> (<a href="https://docs.x.ai/developers/model-capabilities/video/generation" target="_blank" rel="noreferrer">video/generation</a>).</p><p>Official constraints:</p><table tabindex="0"><thead><tr><th>Knob</th><th>Official range</th></tr></thead><tbody><tr><td><code>duration</code></td><td>1–15 seconds</td></tr><tr><td><code>aspect_ratio</code></td><td><code>1:1</code>, <code>16:9</code> / <code>9:16</code> (default <code>16:9</code>), <code>4:3</code> / <code>3:4</code>, <code>3:2</code> / <code>2:3</code></td></tr><tr><td><code>resolution</code></td><td><code>480p</code> (default), <code>720p</code>, <code>1080p</code> on <code>grok-imagine-video-1.5</code> for text-to-video and image-to-video. Reference-to-video is capped at 720p</td></tr><tr><td>Status</td><td><code>pending</code> → <code>done</code> / <code>expired</code> / <code>failed</code></td></tr><tr><td>Modes (one per request)</td><td>text-to-video, image-to-video, reference-to-video, edit-video, extend-video</td></tr></tbody></table><p>Do <strong>not</strong> send <code>image</code> and <code>reference_images</code> together (400). Video URLs are temporary.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">REQUEST_ID</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.x.ai/v1/videos/generations</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$XAI_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;model&quot;: &quot;grok-imagine-video-1.5&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;prompt&quot;: &quot;A glowing crystal-powered rocket launching from Mars&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;duration&quot;: 10,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;aspect_ratio&quot;: &quot;16:9&quot;,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;resolution&quot;: &quot;720p&quot;</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">  }&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -r</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;.request_id&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://api.x.ai/v1/videos/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$REQUEST_ID</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$XAI_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span></span></code></pre></div><p>The xAI SDK&#39;s <code>generate()</code> polls for you. REST users must poll.</p><p>Voice on video: preset <code>voice_id</code> values (same roster as TTS) are generally available on reference-to-video. <strong>Voice references from your own audio files</strong> are trusted-partner only, <a href="https://x.ai/contact-sales?interest=imagine" target="_blank" rel="noreferrer">on request</a> (<a href="https://docs.x.ai/developers/model-capabilities/video/generation" target="_blank" rel="noreferrer">video/generation</a>, <a href="https://x.ai/news/grok-imagine-video-1-5-references" target="_blank" rel="noreferrer">news</a>).</p><p>Generated media is subject to content-policy review and is <strong>not used for training</strong> (<a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">imagine</a>). Enterprise bullets on that page: SOC 2 Type II, HIPAA eligible, GDPR, data residency, SSO &amp; RBAC.</p><h2 id="when-to-use-which" tabindex="-1">When to use which <a class="header-anchor" href="#when-to-use-which" aria-label="Permalink to &quot;When to use which&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want</th><th>Use</th></tr></thead><tbody><tr><td>A poster / clip inside Grok</td><td>Product Imagine on grok.com/imagine or in chat</td></tr><tr><td>Images or video inside your product</td><td>Imagine API</td></tr><tr><td>A working website / game with a <code>*.grok.me</code> link</td><td><strong>Build Mode</strong> on grok.com, not Imagine (<a href="https://x.ai/grok/build-mode" target="_blank" rel="noreferrer">x.ai/grok/build-mode</a>)</td></tr><tr><td>Edits in a real git repo</td><td><a href="./grok-cli.html">Grok Build</a></td></tr></tbody></table><h2 id="common-pitfalls" tabindex="-1">Common pitfalls <a class="header-anchor" href="#common-pitfalls" aria-label="Permalink to &quot;Common pitfalls&quot;">​</a></h2><ul><li>Mixing the product <strong>5-image</strong> editor with the API <strong>3-image</strong> edit cap.</li><li>Assuming API 1080p works on every mode — reference-to-video is 720p; editing keeps the input resolution, capped at 720p.</li><li>Leaving Imagine output on the temporary URL.</li><li>Treating Imagine as &quot;Grok 4.3 with 2M context&quot;. Image/video slugs are <code>grok-imagine-*</code>. The coding flagship is <code>grok-4.6</code>.</li><li>Removing the product watermark. Officially forbidden.</li></ul><h2 id="official-docs" tabindex="-1">Official docs <a class="header-anchor" href="#official-docs" aria-label="Permalink to &quot;Official docs&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use</th></tr></thead><tbody><tr><td><a href="https://grok.com/imagine" target="_blank" rel="noreferrer">grok.com/imagine</a></td><td>Consumer studio</td></tr><tr><td><a href="https://docs.x.ai/grok/overview" target="_blank" rel="noreferrer">docs.x.ai/grok/overview</a></td><td>Imagine as a chat capability</td></tr><tr><td><a href="https://docs.x.ai/grok/faq" target="_blank" rel="noreferrer">docs.x.ai/grok/faq</a></td><td>Watermark, NSFW, 720p fallback, weekly pool</td></tr><tr><td><a href="https://docs.x.ai/developers/model-capabilities/imagine" target="_blank" rel="noreferrer">docs.x.ai/developers/model-capabilities/imagine</a></td><td>API overview</td></tr><tr><td><a href="https://docs.x.ai/developers/model-capabilities/images/generation" target="_blank" rel="noreferrer">images/generation</a></td><td>Still images</td></tr><tr><td><a href="https://docs.x.ai/developers/model-capabilities/video/generation" target="_blank" rel="noreferrer">video/generation</a></td><td>Video</td></tr><tr><td><a href="https://x.ai/api/imagine" target="_blank" rel="noreferrer">x.ai/api/imagine</a></td><td>API marketing</td></tr><tr><td><a href="https://x.ai/news/grok-imagine-image-2" target="_blank" rel="noreferrer">x.ai/news/grok-imagine-image-2</a></td><td>Image 2.0 / Quality Mode</td></tr><tr><td><a href="https://x.ai/news/grok-imagine-video-1-5-references" target="_blank" rel="noreferrer">x.ai/news/grok-imagine-video-1-5-references</a></td><td>1080p, references</td></tr></tbody></table><h2 id="related-pages" tabindex="-1">Related pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related pages&quot;">​</a></h2><ul><li><a href="./grok-chat.html">Grok Chat</a> — Imagine also lives inside a thread</li><li><a href="./grok-voice.html">Voice</a> — TTS roster reused as video preset voices</li><li><a href="./">Grok learning map</a></li><li><a href="./grok-glossary.html">Glossary</a></li></ul>`,43)])])}const f=a(s,[["render",r]]);export{u as __pageData,f as default};
